ai7(a,b){return"\u0627\u0646\u0636\u0645 \u0625\u0644\u064a\u0646\u0627: **"+a+"**. \u062c\u0639\u0644\u062a \u0627\u0644\u0633\u0642\u0641 \u0648\u0627\u0633\u0639\u064b\u0627\u061b \u0648\u0643\u0627\u0646 \u0627\u0644\u0628\u0627\u0626\u0639 \u0633\u064a\u0646\u0632\u0644 \u0625\u0644\u0649 "+b+"."},
gajx(){return"\u062a\u0633\u0644\u0651\u0645 \u0644\u0627\u0639\u0628\u0643 \u0627\u0644\u0641\u0627\u0626\u0636 \u0625\u0644\u0649 \u0648\u0643\u0627\u0644\u0629. \u062a\u0635\u0644 \u0627\u0644\u0648\u0643\u0627\u0644\u0627\u062a \u0625\u0644\u0649 \u0623\u0646\u062f\u064a\u0629 \u0645\u062e\u062a\u0644\u0641\u0629\u061b \u0648\u062a\u064f\u0638\u0647\u0631 \u0643\u0644 \u0628\u0637\u0627\u0642\u0629 **\u0645\u0627 \u062a\u062d\u0635\u0644 \u0639\u0644\u064a\u0647 \u0625\u0646 \u0628\u064a\u0639**. \u0627\u062e\u062a\u0631 \u0648\u0627\u062d\u062f\u0629 \u0648**\u0627\u0639\u0631\u0636\u0647 \u0644\u0644\u0628\u064a\u0639**."},
gajA(){return"\u0623\u0643\u0651\u062f: \u0628\u0639\u062f \u0641\u062a\u062d \u0627\u0644\u0639\u0631\u0636 \u0644\u0627 \u064a\u0645\u0643\u0646 \u0633\u062d\u0628\u0647."},
ajB(a){return"\u0641\u064f\u062a\u062d \u0627\u0644\u0639\u0631\u0636. **"+a+"**."},
