ajC(a,b,c){return"\u0641\u0627\u0632 **"+a+"**: **"+b+"**. \u0648\u0635\u0644\u062a "+c+" \u0625\u0644\u0649 \u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0641\u0627\u0631\u062a\u0641\u0639 \u0627\u0644\u0633\u0639\u0631. \u062a\u0623\u062e\u0630 \u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u062d\u0635\u062a\u0647\u0627\u060c \u0648\u0627\u0644\u0628\u0627\u0642\u064a \u0644\u062e\u0632\u064a\u0646\u062a\u0643."},
ajD(a,b,c,d,e){return"\u0641\u0627\u0632 **"+a+"**: **"+b+"**. \u0644\u0627 \u062a\u0635\u0644 "+c+" \u0625\u0644\u0649 \u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0627\u0644\u0643\u0628\u0631\u0649\u061b \u0648\u0645\u0639 "+d+" \u0643\u0627\u0646 \u0623\u0639\u0644\u0649 \u0639\u0631\u0636 \u0633\u064a\u0628\u0644\u063a "+e+". \u062a\u0623\u062e\u0630 \u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u062d\u0635\u062a\u0647\u0627\u060c \u0648\u0627\u0644\u0628\u0627\u0642\u064a \u0644\u062e\u0632\u064a\u0646\u062a\u0643."},
