aiE(a,b,c){return"\u064a\u0633\u0623\u0644\u0643 \u0645\u062f\u064a\u0631\u0643: \u064a\u0631\u064a\u062f \u0646\u0627\u062f\u064d \u0627\u0644\u062c\u0644\u0648\u0633 \u0625\u0644\u0649 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0645\u0646 \u0623\u062c\u0644 **"+a+"**. **"+b+"** \u0623\u0648 **"+c+"**."},
aiL(a){return"\u0625\u0646 \u0644\u0645 \u062a\u0628\u0639 \u062a\u064f\u063a\u0644\u0642 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0648\u064a\u0636\u064a\u0639 \u0627\u0644\u0639\u0631\u0636. \u0627\u0636\u063a\u0637 **"+a+"**\u061b \u0644\u0646\u0646\u0638\u0631 \u0641\u064a\u0647 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649."},
aiD(a){return"\u0644\u0646\u062a\u062d\u062f\u062b \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0629: **"+a+"**."},
aiI(a){return"\u062d\u062f\u062f \u0644\u0647 **\u062d\u062f\u064b\u0627 \u0623\u062f\u0646\u0649**: \u0644\u0646 \u064a\u0628\u064a\u0639 \u0628\u0623\u0642\u0644 \u0645\u0646\u0647. \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649 \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u064a\u062d\u0642\u0642 \u0633\u0639\u0631\u064b\u0627 \u0623\u0641\u0636\u0644\u060c \u0644\u0643\u0646 \u0625\u0646 \u062a\u062c\u0627\u0648\u0632\u062a \u062d\u062f \u0627\u0644\u0645\u0634\u062a\u0631\u064a \u062a\u062a\u0639\u0637\u0644 \u0627\u0644\u0645\u0641\u0627\u0648\u0636\u0627\u062a. **"+a+"**."},
Oy(a){return"\u062c\u0644\u0633 \u0627\u0644\u0645\u062f\u064a\u0631 \u0625\u0644\u0649 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0648\u0639\u0627\u062f. **"+a+"**\u060c \u062b\u0645 \u0627\u0644\u0645\u0633 \u0627\u0644\u0632\u0631 \u062a\u062d\u062a \u0627\u0644\u0644\u0627\u0639\u0628."},
